// "Doğru Hamle mi?" / "Tek Can" yarışmaları için gnubg-DOĞRULANMIŞ hamle-yargı kartları.
// Her kart: bir açılış pozisyonu + GÖSTERİLEN hamle + o hamle BLUNDER mı (isBlunder).
//   isBlunder=false -> gösterilen = gnubg'nin EN İYİ hamlesi (doğru cevap: "En İyi Hamle")
//   isBlunder=true  -> gösterilen = equity kaybı olan hamle (doğru cevap: "Hatalı Hamle")
// ÜRETİLMİŞ VERİ — elle düzenleme; scripts/judgegen (sunucu gnubg hint listesi) ile yeniden üret.
// Küp yargı kartları AYRI: CUBE_POOL'un 'offer' soruları ArenaGame'de eklenir.
import { openingToQuestion, type Question } from './trainingCurriculum'

export interface JudgeRaw {
  xgid: string
  move: string
  isBlunder: boolean
}

export interface JudgeItem {
  id: string
  state: Question['state']
  kind: 'move' | 'cube'
  move?: string
  isBlunder?: boolean
  cubeAnswer?: 'double' | 'nodouble'
  band?: 'cok_kolay' | 'kolay' | 'orta' | 'zor' | 'cok_zor'
}

