// Ham kartları oynatılabilir JudgeItem'a çevir (xgid -> board state). Geçersizler atılır.
export function buildJudgeMoveItems(): JudgeItem[] {
  const out: JudgeItem[] = []
  for (const r of JUDGE_RAW) {
    const q = openingToQuestion({ xgid: r.xgid, answer: r.move })
    if (!q) continue
    out.push({ id: r.xgid + '|' + r.move, state: q.state, kind: 'move', move: r.move, isBlunder: r.isBlunder })
  }
  return out
}
